/**
 * The calls to action of a post header: share and save side by side, one wide read button, or a wide read button
 * with share and save as icons.
 */
import { type JSX } from "solid-js";
import { Button } from "../primitives/button/button";
import { Group } from "../primitives/group/group";
import { LucideIcon } from "../primitives/lucide-icon/lucide-icon";
import type { Post } from "../blocks/post-card.types";
import type { PostExtras, PostSplitLabels } from "../blocks/post-split.types";

export type PostActionsProps = {
  labels: PostSplitLabels;
  mode?: "pair" | "wide" | "icons";
};

export function PostActions({ labels, mode = "pair" }: PostActionsProps) {
  return (
    <>
      {((mode as string) === "pair") ? (
        <Group gap="2" class="flex-wrap">
          <Button variant="default" size="default" href="#/" class="gap-2" data-testid="action-primary">
            <LucideIcon name="share-2" size={16} />
            {labels.share}
          </Button>
          <Button variant="outline" size="default" href="#/" class="gap-2" data-testid="post-save">
            <LucideIcon name="bookmark" size={16} />
            {labels.save}
          </Button>
        </Group>
      ) : (
        <Group gap="2">
          <Button variant="default" size="default" href="#/" class="gap-2 flex-1" data-testid="action-primary">
            <LucideIcon name="book-open" size={16} />
            {labels.read}
          </Button>
          {((mode as string) === "icons") ? (
            <>
              <Button variant="outline" size="default" layout="icon" aria-label={labels.share} data-testid="post-share">
                <LucideIcon name="share-2" size={16} />
              </Button>
              <Button variant="outline" size="default" layout="icon" aria-label={labels.save} data-testid="post-save">
                <LucideIcon name="bookmark" size={16} />
              </Button>
            </>
